    if(request.containsKey("cascade")){for(const auto& raw:array(request.get("cascade"))->elements())state->cascade->addToTip(decode(raw));state->cascade->cascadeChain();}
    if(request.containsKey("mmr")&&state->tree->getTip()){std::shared_ptr<MMR> mmr;if(!request.get("mmr").isNull()){auto bytes=MiniData::fromHex(request.get("mmr").asString());size_t at=0;mmr=std::make_shared<MMR>(MMR::deserialise(bytes.bytes(),at));}NIOMessageFixture::mmr(*state->tree->getTip(),mmr);}
    NIOMessageFixture::mempool(flag(request,"mempoolFull"),MiniNumber(num(request,"burn",0)));
    if(request.containsKey("db"))for(const auto& raw:array(request.get("db"))->elements()){auto value=std::make_shared<TxPoW>(decode(raw));state->db[value->getTxPoWID()]=value;}
    auto manager=NIOManagerFixture::create(state);NIOManager::runtimeLookup=[manager]{return manager;};NIOClient::runtimeLookup=[manager]{return manager->clientRuntime();};
    auto client=std::make_shared<NIOClient>(flag(request,"incoming"),"127.0.0.1",9001,nullptr,std::make_shared<NativeNIOSelectionKey>([]{}));NIOClientFixture::uid(*client);client->setValidGreeting(flag(request,"valid"));client->setSentGreeting(flag(request,"sent"));if(flag(request,"peerGreeting"))client->setReceivedP2PGreeting();if(!flag(request,"missing"))manager->add(client);
    GeneralParams::TEST_PARAMS=flag(request,"test");GeneralParams::P2P_ENABLED=flag(request,"p2p");GeneralParams::P2P2_ENABLED=flag(request,"p2p2");GeneralParams::TXBLOCK_NODE=flag(request,"slave");GeneralParams::ALLOW_GEN_MESSAGE=flag(request,"allow");GeneralParams::IS_MEGAMMR=flag(request,"mega");GeneralParams::LIMIT_IBD_30MINS=flag(request,"limitIBD");GeneralParams::ARCHIVESYNC_LIMIT_BANDWIDTH=flag(request,"limitBandwidth");GeneralParams::IS_HOST_SET=false;GeneralParams::MINIMA_PORT=0;GeneralParams::RESCUE_MEGAMMR_NODE=flag(request,"rescue")?"fixture":"";
    auto shutdown=flag(request,"shutdown"),sync=flag(request,"sync");
    auto peers=std::make_shared<std::vector<SocketAddressPtr>>();peers->push_back(std::make_shared<InetSocketAddress>("127.0.0.1",9002));
    auto archive=std::make_shared<IBDArchive>();archive->exists=[](auto&){return MiniNumber(-1);};archive->loadSyncBlockRange=[state](const auto& number){state->events.add("archive-sync:"+number.toString());return std::vector<std::shared_ptr<TxBlock>>{};};archive->loadBlockRange=[state](const auto& first,const auto& last,bool descending){state->events.add("archive-range:"+first.toString()+":"+last.toString()+":"+(descending?"true":"false"));return std::vector<std::shared_ptr<TxBlock>>{};};archive->loadLastBlock=[] {return std::shared_ptr<TxBlock>{};};archive->loadCascade=[state]{return state->cascade;};
    IBD::services.getTree=[state]{return state->tree;};IBD::services.getCascade=[state]{return state->cascade;};IBD::services.getArchive=[archive]{return archive;};IBD::services.readLock=[](bool){};IBD::services.isShuttingDown=[shutdown]{return shutdown;};
    Greeting::services.readLock=[](bool){};Greeting::services.getWelcome=[]{return std::optional<std::string>("fixture");};Greeting::services.getTip=[state]{return state->tree->getTip();};Greeting::services.getPeersCopy=[peers]{return peers;};TxPoWSearcher::services.getTip=[state]{return state->tree->getTip();};TxPoWChecker::services.checkMempoolCoins=[&request](const auto&){return flag(request,"mempoolCoin");};
    auto& services=NIOMessage::services;services={};services.isShuttingDownOrRestoring=[shutdown]{return shutdown;};services.isSyncIBD=[sync]{return sync;};services.getTree=[state]{return state->tree;};services.getCascade=[state]{return state->cascade;};services.txPoWExists=[state](const auto& id){state->events.add("exists:"+id);return state->exists||state->db.contains(id);};services.getTxPoW=[state](const auto& id){state->events.add("get:"+id);auto it=state->db.find(id);return it==state->db.end()?nullptr:it->second;};services.findTxBlock=[state](const auto& id){state->events.add("block:"+id);return std::shared_ptr<TxBlock>{};};services.loadArchiveBlock=[state](const auto& id){state->events.add("archive:"+id);return std::shared_ptr<TxBlock>{};};services.addInvalidPeer=[state](const auto& host){state->invalid.insert(host);};services.postP2P=[state](auto message){state->events.add(NIOManagerFixture::event("p2p",message));};services.postP2PTimer=[state](auto message){state->events.add(NIOManagerFixture::timer("p2p",message));};services.postMainTimer=[state](auto message){state->events.add(NIOManagerFixture::timer("main",message));};services.notifyEvent=[state](const auto& name,const auto& data){state->events.add(name);state->events.add(data);};services.postProcessIBD=[state](auto ibd,auto uid){state->events.add("ibd:"+uid.value_or("null")+":"+MiniData(ibd->serialise()).to0xString());};services.postProcessSyncIBD=[state](auto ibd,auto uid){state->events.add("sync:"+uid.value_or("null")+":"+MiniData(ibd->serialise()).to0xString());};services.postProcessTxPoW=[state](auto txpow){state->events.add("pow:"+txpow->getTxPoWID());};services.postProcessTxBlock=[state](auto block){state->events.add("txblock:"+block->getTxPoW().getTxPoWID());};services.getPeersCopy=[peers]{return peers;};services.getP2PClients=[&request]{return float(num(request,"clients",1))/3.0f;};services.getP2P2Peers=[]{return std::make_shared<MiniUtil::StringList>(MiniUtil::StringList{"127.0.0.1:9003",std::nullopt});};services.getAutomineTimer=[]{return int64_t(50000);};services.mineTxPoWAsync=[state](auto txpow){state->events.add("mine:"+txpow->getTxPoWID());};
    NIOMessage::mlastSyncReq.clear();NIOMessage::mLastChainSync.clear();NIOMessage::mHaveSentIBDRecently.clear();NIOMessage::LAST_TXBLOCKMINE_MSG=flag(request,"recentMine")?TimerMessage::currentTimeMillis():0;
